"""Generated bybit earn HTTP methods."""

from typing import Any

from .._market_http import MarketHTTP


class GeneratedEarnHTTP(MarketHTTP):
    """Earn API methods."""

    async def get_earn_auto_savings(self, *, coins: list[Any] | None = None) -> dict[str, Any]:
        """
        Get Auto Savings. GET /v5/earn/flexible-saving/auto-savings.

        Source: https://bybit-exchange.github.io/docs/v5/earn/flexible-saving/auto-savings

        Args:
            coins: Coin names; sent as repeated query parameters, at most 50
        """
        return await self._native_private(
            "get_earn_auto_savings", self._native_params(**{"coins": coins})
        )

    async def set_earn_auto_savings(
        self,
        *,
        coin: str | None = None,
        is_selected: bool,
        purchase_immediately: bool | None = None,
    ) -> dict[str, Any]:
        """
        Set Auto Savings. POST /v5/earn/flexible-saving/auto-savings.

        Source: https://bybit-exchange.github.io/docs/v5/earn/flexible-saving/auto-savings

        Args:
            coin: Coin to update; omit or pass an empty string for the global setting
            is_selected: Whether to enable auto savings
            purchase_immediately: When enabling, subscribe the available Funding Account balance
        """
        return await self._native_private(
            "set_earn_auto_savings",
            self._native_params(
                **{
                    "coin": coin,
                    "isSelected": is_selected,
                    "purchaseImmediately": purchase_immediately,
                }
            ),
        )
